	// The vendored-directory heuristic consults the project's own re-inclusion
	// rules wherever they live, not only at the root, so a tree the project
	// deliberately keeps under a vendored-looking name is not dropped.
	// A .gitignore can itself be ignored while Git still applies its rules to
	// sibling paths. Enumerate the bounded ignored-ignore stream as policy
	// evidence instead of assuming every effective rule file appears in listed.
	nestedIgnores, err := gitutil.BoundedWorktreeNestedIgnorePaths(
		ctx, repo, maxNestedIgnoreFiles, includeEveryNestedIgnore,
	)
	if err != nil {
		return nil, nil, fmt.Errorf("list worktree nested ignore files: %w", err)
	}
	vendorRules, err := worktreeVendorIgnoreRules(repo, ignores, nestedIgnores)
	if err != nil {
		return nil, nil, err
	}
	// Every `gitdir:` pointer this listing can reach is resolved before any
	// verdict is asked, so the answer cannot depend on listing order.
	// One lstat per listed path. Git lists index entries for files staged as
	// deleted and can list a symlink or a gitlink directory; the snapshot reads
	// only regular files, and the gitlink entries are exactly what the excluder
	// must examine for a `.git` pointer.
	// The index decides what a tracked entry IS, because lstat cannot. With
	// core.symlinks=false Git writes a mode-120000 entry to disk as an ordinary
	// file holding the link target, so lstat calls it regular and the worktree
	// listing would admit a symlink the committed listing excludes by mode --
	// the same divergence, reappearing from the other side. A failure here is
	// not fatal: the lstat classification below still applies, which is the
	// behaviour that existed before this consultation.
	indexNonRegular, indexErr := gitutil.IndexNonRegularPaths(ctx, repo)
	if indexErr != nil {
		indexNonRegular = nil
	}
	// The index alone cannot tell a materialized symlink from a replaced one.
	// Both leave mode 120000 in the index with an ordinary file on disk: the
	// first because core.symlinks=false writes the link target as file content,
	// the second because the user deleted the link and wrote a real file there.
	// Only the second holds different bytes than the index entry, and only the
	// second is source a worktree query is supposed to show -- vetoing both made
	// an uncommitted replacement invisible until it was staged, which is the one
	// thing a worktree listing promises not to do.
	indexReplaced := gitutil.IndexReplacedNonRegularPaths(ctx, repo, indexNonRegular)
	kinds := make([]listedPathKind, len(listed))
	var listedDirs []string
	for index, entry := range listed {
		info, statErr := os.Lstat(filepath.Join(repo, filepath.FromSlash(entry)))
		_, nonRegularInIndex := indexNonRegular[filepath.ToSlash(entry)]
		_, replacedInWorktree := indexReplaced[filepath.ToSlash(entry)]
		switch {
		case statErr != nil:
		case info.IsDir():
			kinds[index] = listedPathDir
			listedDirs = append(listedDirs, entry)
		case nonRegularInIndex && !replacedInWorktree:
			// Tracked as a symlink or gitlink and untouched since; not source,
			// whatever it looks like on this filesystem.
		case info.Mode()&fs.ModeSymlink == 0 && info.Mode().IsRegular():
			kinds[index] = listedPathRegular
		}
	}
	gitDirs := newGitDirExcluder(ctx, repo)
	// The directories git lists nothing under come from git itself, so the sweep
	// for a suppressed `.git` pointer does not have to re-read the whole tree.
	// An IGNORED tree is in neither of git's `--exclude-standard` listings, so no
	// chain and no collapsed root reaches a `.git` pointer inside it — and that
	// pointer names a git directory somewhere ELSE, which git does list.
	// `.gitignore` is committed content in the repository being scanned, so
	// leaving those trees unswept let the scanned repository choose which
	// pointers this rule may read. Ask git for them by name.
	gitDirs.unlistedRoots, gitDirs.gitAnsweredRoots = gitSweepRootsFromGit(ctx, repo, gitDirs)
	gitDirs.observeListedPaths(listed, listedDirs)
	if err := gitDirs.listedObservationError(); err != nil {
		return nil, nil, err
	}
	paths := make([]string, 0, len(listed))
	seen := make(map[string]struct{}, len(listed))
	for index, entry := range listed {
		rel := filepath.ToSlash(entry)
		if _, exists := seen[rel]; exists {
			continue
		}

	commit, tree, err := HeadCommitAndTree(t.Context(), repo)
	if err != nil {
		t.Fatal(err)
	}
	wantCommit, err := RevParse(t.Context(), repo, "HEAD")
	if err != nil {
		t.Fatal(err)
	}
	if commit != wantCommit {
		t.Fatalf("commit = %q, want %q", commit, wantCommit)
	}
	wantTree, err := RevParse(t.Context(), repo, "HEAD^{tree}")
	if err != nil {
		t.Fatal(err)
	}
	if tree != wantTree {
		t.Fatalf("tree = %q, want %q", tree, wantTree)
	}

	git(t, repo, "tag", "-a", "v1", "-m", "annotated tag")
	git(t, repo, "symbolic-ref", "HEAD", "refs/tags/v1")
	commit, tree, err = HeadCommitAndTree(t.Context(), repo)
	if err != nil {
		t.Fatalf("annotated-tag HEAD: %v", err)
	}
	if commit != wantCommit || tree != wantTree {
		t.Fatalf("annotated-tag provenance = %q/%q, want %q/%q", commit, tree, wantCommit, wantTree)
	}
}

