		}
		if readErr == nil {
			continue
		}
		waitErr := cmd.Wait()
		if !errors.Is(readErr, io.EOF) {
			return nil, readErr
		}
		if waitErr != nil {
			message := strings.TrimSpace(stderr.String())
			if message == "" {
				message = waitErr.Error()
			}
			return nil, errors.New(message)
		}
