	gitCmd(t, repo, "add", "src.go/staged.go")
	stagedDirectory := filepath.Join(repo, "src.go")
	movedDirectory := filepath.Join(t.TempDir(), "staged-src.go")
	if err := os.Rename(stagedDirectory, movedDirectory); err != nil {
		t.Fatal(err)
