	listed, err := listWorktreeFiles(ctx, repo)
	if err != nil {
		if errors.Is(err, gitutil.ErrWorktreeListingTruncated) {
			return nil, nil, fmt.Errorf("list Git worktree paths: %w", err)
		}
		if repositoryHasGitMetadata(repo) {
			return walkWorktreeFilesAfterGitFailure(ctx, repo, ignores, dirTracked, err)
		}
		return walkWorktreeFiles(ctx, repo, ignores, dirTracked)
	}
	if hasIncludeFiles {
		// An explicit include file's negations are allowed to reach into ignored
		// content; nothing else is, so the ignored listing is only ever requested
		// when such a file was supplied.
		ignored, ignoredErr := gitutil.ListIgnoredWorktreeFiles(ctx, repo)
		if ignoredErr != nil {
			return nil, nil, fmt.Errorf("list ignored Git worktree paths for explicit includes: %w", ignoredErr)
		}
		for _, rel := range ignored {
			if ignores.Reincluded(filepath.ToSlash(rel), false) {
				listed = append(listed, rel)
			}
		}
	}
	// The vendored-directory heuristic consults the project's own re-inclusion
		t.Fatalf("requested repository's tracked source is missing: %#v", snapshot.Files)
	}
	if snapshotHasPath(snapshot, "pkg/secret.go") || snapshotHasSymbol(snapshot, "AmbientOverrideSecret") {
		t.Fatalf("inherited Git repository overrides changed the requested corpus: %#v", snapshot.Files)
	}
}

func TestWorktreeSnapshotWarnsAndRetainsTrackedAmbiguousDirectoryWhenGitFails(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("the selective Git wrapper is a POSIX shell script")
	}
	repo := t.TempDir()
	initRepo(t, repo)
	writeFile(t, repo, "build/keep.go", "package build\nfunc KeepOnFallback() {}\n")
	git(t, repo, "add", ".")
	git(t, repo, "commit", "-m", "tracked ambiguous directory")

	realGit, err := exec.LookPath("git")
	if err != nil {
		t.Fatal(err)
	}
	binDir := t.TempDir()
	wrapper := filepath.Join(binDir, "git")
	script := "#!/bin/sh\ncase \"$*\" in *\"ls-files\"*) exit 41;; esac\nexec \"$REAL_GIT\" \"$@\"\n"
	if err := os.WriteFile(wrapper, []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("REAL_GIT", realGit)
	t.Setenv("PATH", binDir)

	snapshot, err := BuildProviderSnapshotWithOptions(t.Context(), repo, "test-version", ProviderSnapshotOptions{Worktree: true})
	if err != nil {
		t.Fatal(err)
	}
	if !snapshotHasSymbol(snapshot, "KeepOnFallback") {
		t.Fatalf("fallback treated a potentially tracked ambiguous directory as untracked: %#v", snapshot.Files)
	}
	warned := false
	for _, warning := range snapshot.Header.Warnings {
		warned = warned || warning.Code == "W_GIT_WORKTREE_FALLBACK"
